 const phAll=ready&&typeof isPhrase==='function'?bank.filter(w=>wordInDeck(w,'phrase')):[],phSeen=phAll.filter(w=>wordRec(w.id).seen>0).length,phNext=phAll.length?topicNextWords('p:all'):[];
 const lvCount=n=>{if(!ready)return '';const ws=bank.filter(w=>wordInDeck(w,'general')&&w.studyRank&&inLevelRange(w.studyRank,n));return ws.length.toLocaleString()};
 const levels=typeof WORD_LEVELS!=='undefined'?`<li class="h-levels" role="group" aria-label="単語の学習範囲">${[...WORD_LEVELS,[0,'全部']].map(([n,t])=>`<button class="${wordState.level===n?'on':''}" title="${n?(([lo,hi])=>hi===Infinity?`${lo.toLocaleString()}語目〜`:`${lo.toLocaleString()}〜${hi.toLocaleString()}語目`)(levelRange(n)):'すべての語'}" aria-pressed="${wordState.level===n}" onclick="setWordLevel(${n})"><b>${t}</b>${ready?`<small>${lvCount(n)}語</small>`:''}</button>`).join('')}</li>`:'';
