function reviewDueWords(){return typeof bank!=='undefined'&&typeof bankStatus!=='undefined'&&bankStatus==='ready'?bank.filter(w=>dueWord(w)):[]}
function startWordReview(kind){const ids=reviewDueWords().slice(0,20).map(w=>w.id);if(!ids.length)return;view='words';wordCurrent=null;wordTopic='';startWords(kind,ids)}
