function review(){if(typeof loadWordBank==='function'&&bankStatus==='idle')loadWordBank();const ready=bankStatus==='ready',due=reviewDueWords(),n=due.length,m=state.missed.length;
 const card=(icon,title,sub,btns)=>`<div class="panel review-entry r-card"><div class="r-head"><span class="r-count${icon===0?' is-zero':''}">${icon}</span><div><h2>${title}</h2><p class="subtext">${sub}</p></div></div><div class="r-actions">${btns}</div></div>`;
 return `<h1>復習</h1>${card(ready?n:'…','単語',!ready?'読み込んでいます…':n?`復習の時期が来た語・復習に登録した語が ${n} 語あります${n>20?'（1回20語まで）':''}。テストで正解すると外れます（カードだけでは残ります）。`:'今日復習する単語はありません。',ready&&n?`<button class="btn" onclick="startWordReview('cards')">カードで復習</button><button class="btn light" onclick="startWordReview('quiz')">テストで復習</button>`:'')}${card(m,'文法',m?`確認テストで間違えた問題が ${m} 問あります。正解すると外れます。`:'間違えた問題はありません。',m?`<button class="btn" onclick="startQuiz([...state.missed],'review')">もう一度解く</button>`:'')}<p class="r-more"><button class="textbtn" onclick="startMixedQuiz()">文法：全${lessons.length}課のまとめテスト →</button>${state.wrong.length?`<button class="textbtn" onclick="moduleFilter='all';go('course')">間違えた課を見る（${state.wrong.length}課）→</button>`:''}</p><section class="r-history" aria-label="復習の履歴"><div class="section-head"><h2>単語の復習の履歴</h2></div>${ready&&typeof reviewHistoryHTML==='function'?reviewHistoryHTML():''}</section>`}
// 保存した文法 now lives in the grammar page as the 保存 chip; the old view opens it there.
function saved(){moduleFilter='saved';view='course';return course()}
// お気に入り: everything starred in one place (words, phrases, slang, saved grammar), with card / test practice.
let favTab='';
function favWords(deck){return typeof bankStatus!=='undefined'&&bankStatus==='ready'?bank.filter(w=>wordRec(w.id).favorite&&(!deck||deckOf(w)===deck)):[]}
function startFavPractice(kind){const ids=shuffle(favWords(favTab==='grammar'?'':favTab).map(w=>w.id)).slice(0,20);if(!ids.length)return;view='words';wordCurrent=null;wordTopic='';startWords(kind,ids)}
function openFavWord(id){const w=bankMap.get(id);if(!w)return;view='words';wordDeck=deckOf(w);wordTopic='';openWord(id)}
// お気に入り: one tab per kind (単語 / フレーズ / 口語・スラング / 文法) so each list starts at the top; practise the open tab with カード / テスト.
function favorites(){if(typeof loadWordBank==='function'&&bankStatus==='idle')loadWordBank();const ready=bankStatus==='ready',gram=state.saved.map(id=>lessons[id-1]).filter(Boolean);
 const tabs=[['general','単語'],['phrase','フレーズ'],['slang','口語・スラング']].map(([d,t])=>[d,t,favWords(d)]).concat([['grammar','文法',gram]]);
 if(!tabs.some(([d])=>d===favTab))favTab=(tabs.find(([,,xs])=>xs.length)||tabs[0])[0];
 const cur=tabs.find(([d])=>d===favTab),xs=cur[2],unit=favTab==='phrase'?'フレーズ':favTab==='grammar'?'課':'語';
 const row=w=>`<li><button class="f-main" onclick="openFavWord('${w.id}')"><span class="f-term"><b>${esc(w.ro)}</b> <span lang="th">${esc(w.th)}</span></span><small>${esc(w.meanings[0].ja)}</small></button>${wordAudio(w.id,'')}<button class="w-iconbtn on" onclick="favoriteWord('${w.id}')" aria-label="${esc(w.th)}をお気に入りから解除" aria-pressed="true">${icon('star')}</button></li>`;
 return `<h1>お気に入り</h1>${!ready?'<div class="empty" role="status">読み込んでいます…</div>':`<div class="x-seg f-tabs" role="tablist" aria-label="お気に入りの種類">${tabs.map(([d,t,list])=>`<button role="tab" aria-selected="${favTab===d}" onclick="favTab='${d}';render()">${t}<small>${list.length}</small></button>`).join('')}</div>${!xs.length?`<div class="empty"><h3>${cur[1]}のお気に入りはまだありません</h3><p class="subtext">${favTab==='grammar'?'文法の課で「保存」を押すとここに集まります。':'一覧や詳細の ☆ を押すとここに集まります。'}</p></div>`:favTab==='grammar'?xs.map(l=>lessonRow(l)).join(''):`<section class="x-practice" aria-label="お気に入りを練習"><div class="x-practice-head"><h2>${cur[1]}を練習</h2><span>${xs.length.toLocaleString()}${unit}から${Math.min(20,xs.length)}${unit}</span></div><div class="x-practice-btns"><button class="x-pr" onclick="startFavPractice('cards')"><b>カード</b><small>めくって自分で確認<br>復習には残ります</small></button><button class="x-pr is-test" onclick="startFavPractice('quiz')"><b>テスト</b><small>4択で確認<br>正解で復習から外れます</small></button></div></section><ul class="f-list">${xs.map(row).join('')}</ul>`}`}`}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
// Each lesson has 10 check questions: the original one (index 0) plus nine in lesson-quizzes.js.
// Answering all 10 of a lesson in one run completes the lesson (履修済み). Missed questions are kept as "id:index".
const THAI_CHAR=/[฀-๿]/;
function lessonQuestions(id){const l=lessons[id-1],x=typeof LESSON_QUIZZES==='undefined'?null:LESSON_QUIZZES[id];return [{q:l.q,options:l.options.map((o,i)=>(x?.existingRo?x.existingRo[i]:THAI_CHAR.test(o))?{th:o,ro:x?.existingRo?.[i]||''}:{ja:o}),answer:l.answer,why:l.why},...(x?.questions||[])]}
function quizItem(key){const [id,k]=String(key).split(':').map(Number);return {id,k:k||0,key:`${id}:${k||0}`}}
function syncWrong(){state.missed=[...new Set(state.missed)].filter(key=>{const x=quizItem(key);return lessons[x.id-1]&&lessonQuestions(x.id)[x.k]});state.wrong=[...new Set(state.missed.map(key=>quizItem(key).id))]}
function startLessonQuiz(id){if(typeof LESSON_QUIZZES==='undefined'&&typeof loadLazyScript==='function'){loadLazyScript('lesson-quizzes.js').then(()=>startLessonQuiz2(id));return}startLessonQuiz2(id)}
function startLessonQuiz2(id){startQuiz(lessonQuestions(id).map((_,k)=>`${id}:${k}`),'lesson')}
function startMixedQuiz(){if(typeof LESSON_QUIZZES==='undefined'&&typeof loadLazyScript==='function'){loadLazyScript('lesson-quizzes.js').then(startMixedQuiz);return}startQuiz(shuffle(orderedLessons.map(l=>`${l.id}:${Math.floor(Math.random()*lessonQuestions(l.id).length)}`)),'review')}
function startQuiz(items,origin){quiz={ids:items.map(x=>quizItem(x).key),i:0,results:[],choice:null,order:shuffle([0,1,2]),origin};view='quiz';render();window.scrollTo(0,0)}
function currentQuestion(){const x=quizItem(quiz.ids[quiz.i]);return {...x,l:lessons[x.id-1],q:lessonQuestions(x.id)[x.k]}}
function answer(n){if(quiz.choice!==null)return;quiz.choice=n;const {id,key,q}=currentQuestion(),ok=n===q.answer;quiz.results.push(ok);
 if(ok)state.missed=state.missed.filter(x=>x!==key);else if(!state.missed.includes(key))state.missed.push(key);
 if(quiz.origin==='lesson'&&quiz.results.length===quiz.ids.length){if(quiz.results.every(Boolean)){if(!state.done.includes(id))state.done.push(id);if(!state.passed.includes(id))state.passed.push(id);quiz.completed=true}else state.passed=state.passed.filter(x=>x!==id)}
 syncWrong();save();render()}
function nextQuestion(){quiz.i++;quiz.choice=null;quiz.order=shuffle([0,1,2]);render();window.scrollTo(0,0)}
// Grammar pages write the velar nasal as ŋ (romanizeThai); quiz data uses ng.
const quizRo=ro=>String(ro).replace(/ng/g,'ŋ');
function quizOption(o){return o.th?`<span class="quiz-ro" lang="th-Latn">${esc(o.ro?quizRo(o.ro):romanizeThai(o.th))}</span><span class="quiz-th" lang="th">${esc(o.th)}</span>`:`<span class="quiz-ja">${esc(o.ja)}</span>`}
function quizView(){if(quiz.i>=quiz.ids.length){const yes=quiz.results.filter(Boolean).length,all=yes===quiz.ids.length,lessonRun=quiz.origin==='lesson',l=lessons[quizItem(quiz.ids[0]).id-1];return `<div class="quiz-wrap"><div class="empty quiz-result${lessonRun&&all?' is-complete':''}"><div class="eyebrow">${lessonRun?`LESSON ${displayNumber(l.id)}`:'確認テストの結果'}</div><h1>${yes} / ${quiz.ids.length} 問 正解</h1><p class="subtext">${lessonRun?(all?'全問正解！この単元を履修済みにしました。':`全${quiz.ids.length}問正解で履修済みになります。間違えた問題は「復習」に残りました。`):(all?'よくできました。例文を声に出して、会話につなげよう。':'間違えた問題を復習リストに保存しました。解説と例文を確認して、もう一度。')}</p><div class="settings-row" style="justify-content:center"><button class="btn" onclick="startQuiz([...quiz.ids],quiz.origin)">もう一度解く</button>${lessonRun&&all&&orderedLessons[orderedLessons.length-1].id!==l.id?`<button class="btn light" onclick="openLesson(${orderedLessons[orderedLessons.findIndex(x=>x.id===l.id)+1].id})">次のレッスンへ →</button>`:''}<button class="btn light" onclick="${lessonRun?`openLesson(${l.id})`:"go('review')"}">戻る</button></div></div></div>`}
 const {l,q}=currentQuestion(),answered=quiz.choice!==null,ok=quiz.choice===q.answer;return `<div class="quiz-wrap"><button class="textbtn back" onclick="${quiz.origin==='lesson'?`openLesson(${l.id})`:"go('review')"}">← 問題を終了する</button><div class="quiz-top"><span class="subtext">${quiz.i+1} / ${quiz.ids.length} 問${quiz.origin==='lesson'?'<small> · 全問正解で履修済み</small>':''}</span><div class="track"><div style="width:${quiz.i/quiz.ids.length*100}%"></div></div></div><section class="panel"><div class="eyebrow">LESSON ${displayNumber(l.id)} · ${modules[l.m].name}</div><h2 class="quiz-q">${esc(q.q)}</h2>${q.sentence?`<div class="quiz-sentence">${q.sentence.th?`<span class="quiz-th" lang="th">${esc(q.sentence.th)}</span>`:''}${q.sentence.ro?`<span class="quiz-ro" lang="th-Latn">${esc(quizRo(q.sentence.ro))}</span>`:''}${q.sentence.ja?`<span class="quiz-sentence-ja">${esc(q.sentence.ja)}</span>`:''}</div>`:''}${quiz.order.map(n=>`<button class="option quiz-option ${answered&&n===q.answer?'correct':''} ${answered&&n===quiz.choice&&!ok?'wrong':''}" ${answered?'disabled':''} onclick="answer(${n})">${answered&&n===q.answer?'<span class="quiz-mark">✓</span>':''}${quizOption(q.options[n])}</button>`).join('')}${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'正解！':'もう一度、形を確かめよう。'}</strong><br>${esc(q.why)}</div><div class="bottom-actions"><button class="textbtn" onclick="openLesson(${l.id})">文法の解説に戻る</button><button class="btn" onclick="nextQuestion()">${quiz.i===quiz.ids.length-1?'結果を見る':'次の問題'} →</button></div>`:''}</section></div>`}
function settings(){const vs=voices.filter(v=>/^th/i.test(v.lang));return `<h1>音声・学習データ</h1><section class="panel"><h2>タイ語の音声</h2><p class="subtext">端末・ブラウザのタイ語読み上げを使用します。再生音は端末の音声エンジンにより異なります。</p><label class="settings-label" for="voice">音声を選ぶ</label><select class="field" id="voice" onchange="state.voice=this.value;save()"><option value="">自動選択（タイ語）</option>${vs.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===state.voice?'selected':''}>${esc(v.name)}</option>`).join('')}</select><p class="subtext">${vs.length?`タイ語の音声が ${vs.length} 件あります。`:'タイ語音声が一覧にありません。再生できない場合は、端末の読み上げ設定でタイ語の音声を追加し、Chromeなどで開き直してください。'}</p><label class="settings-label" for="speed">通常再生の速さ</label><select class="field" id="speed" onchange="state.speed=Number(this.value);save()">${[[.75,'ゆっくり（0.75）'],[.85,'少しゆっくり（0.85）'],[1,'標準（1.0）']].map(([v,t])=>`<option value="${v}" ${Number(state.speed)===v?'selected':''}>${t}</option>`).join('')}</select><div style="margin-top:18px"><button class="speak is-icon" aria-label="音声を試す（ถึงแล้วนะ）" title="音声を試す" onclick="speak(13,1)">${icon('audio')}</button><button class="textbtn" style="margin-left:15px" onclick="if('speechSynthesis'in window)speechSynthesis.cancel()">再生を止める</button></div></section><section class="panel"><h2>声調付きローマ字について</h2><p class="subtext">本アプリは声調を「無印＝中平・à＝低・â＝下降・á＝高・ǎ＝上昇」で表記します。母音の重複は長母音、ʉ・ə・ɛ・ɔ はタイ語の母音を区別する記号です。ローマ字は発音の目安として使い、音声も一緒に確認してください。</p></section><section class="panel"><h2>学習記録のバックアップ</h2><p class="subtext">文法の進捗と、単語の学習・お気に入り・復習日は、このブラウザに記録されます。他の端末に移す場合は書き出して読み込んでください。${storageOK?'':' 現在、ブラウザの保存が利用できません。'}</p><div class="settings-row"><button class="btn light" onclick="exportData()">データを書き出す ↓</button><label class="btn light" for="import">データを読み込む ↑</label><input hidden type="file" id="import" accept="application/json,.json" onchange="importData(this.files[0])"></div><p class="subtext" style="margin:18px 0 0">読み込みは現在の記録を置き換えます。</p><button class="textbtn danger" style="margin-top:20px" onclick="resetData()">文法の学習記録をリセット</button><button class="textbtn danger" style="margin-left:18px" onclick="resetWordData()">単語の学習記録をリセット</button></section>`}
function exportData(){const b=new Blob([JSON.stringify({app:KEY,version:1,state,words:wordState,script:scriptState},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='thai-steps-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('バックアップを書き出しました。')}
async function importData(file){if(!file)return;try{const d=JSON.parse(await file.text());if(d.app!==KEY||d.version!==1||!d.state||!['done','saved','wrong','passed'].every(k=>Array.isArray(d.state[k])&&d.state[k].every(x=>Number.isInteger(x)&&x>=1&&x<=lessons.length)))throw Error();if(!confirm('現在の学習記録を、選んだバックアップに置き換えますか？'))return;const n=fresh();for(const k of ['done','saved','wrong','passed'])n[k]=[...new Set(d.state[k])];if([.75,.85,1].includes(d.state.speed))n.speed=d.state.speed;n.voice=typeof d.state.voice==='string'?d.state.voice:'';n.hideTranslation=!!d.state.hideTranslation;n.missed=Array.isArray(d.state.missed)?d.state.missed.filter(x=>typeof x==='string'&&/^\d+:\d+$/.test(x)):n.wrong.map(id=>id+':0');state=n;syncWrong();if(d.words&&typeof d.words.records==='object'&&!Array.isArray(d.words.records)){wordState=sanitizeWordState(d.words);saveWords()}if(d.script&&Array.isArray(d.script.done)){scriptState={done:d.script.done.filter(x=>typeof x==='string'),games:typeof sanitizeScriptGames==='function'?sanitizeScriptGames(d.script.games):{}};saveScript()}save();render();toast('学習記録を読み込みました。')}catch(e){toast('Thai Steps の有効なバックアップファイルを選んでください。')}}
function resetData(){if(!confirm('履修済み・確認テスト・復習リスト・保存した文法をすべて消去します。よろしいですか？'))return;state=fresh();save();render();toast('学習記録をリセットしました。')}
