let lastView=null,keepSearch=false;
function render(){if(view!=='scriptGame'&&typeof scriptGameStop==='function')scriptGameStop();if(view!==lastView){if(lastView!==null&&!keepSearch){if(typeof wordQuery!=='undefined')wordQuery='';search=''}keepSearch=false;lastView=view}if(document.body)document.body.dataset.view=view;nav();$('#crumb').textContent=({words:typeof wordDeck!=='undefined'&&wordDeck==='phrase'?'フレーズ学習':'単語学習',home:'学習ホーム',course:'文法',lesson:`文法 / ${modules[lessons[current-1].m].name}`,review:'復習',extra:typeof extraFrom!=='undefined'&&extraFrom==='script'?'文字 / 0. 発音と声調':'文法 / 0. 数字',favorites:'お気に入り',saved:'保存した文法',quiz:'確認テスト',build:'文法 / 並べ替え練習',settings:'音声・学習データ',script:'文字',scriptLesson:'文字',scriptQuiz:'文字 / 確認テスト',scriptGame:'文字 / ゲーム'})[view];$('#main').innerHTML=({words:wordsView,home,course,lesson,review,favorites,saved,...(typeof extraView==='function'?{extra:extraView}:{}),quiz:quizView,...(typeof buildView==='function'?{build:buildView}:{}),settings,...(typeof scriptView==='function'?{script:scriptView,scriptLesson:scriptLessonView,scriptQuiz:scriptQuizView}:{}),...(typeof scriptGameView==='function'?{scriptGame:scriptGameView}:{})})[view]();if(view!=='words'&&!view.startsWith('script'))annotateReadings($('#main'));document.title=`Thai Steps | ${$('#crumb').textContent}`}
